class FirstTrueTests(TestCase):
    """Tests for ``first_true()``"""

    def test_something_true(self):
        """Test with no keywords"""
        self.assertEqual(mi.first_true(range(10)), 1)

    def test_nothing_true(self):
        """Test default return value."""
        self.assertIsNone(mi.first_true([0, 0, 0]))

    def test_default(self):
        """Test with a default keyword"""
        self.assertEqual(mi.first_true([0, 0, 0], default='!'), '!')

    def test_pred(self):
        """Test with a custom predicate"""
        self.assertEqual(
            mi.first_true([2, 4, 6], pred=lambda x: x % 3 == 0), 6
        )

def _read_table(self) -> dict[str, Mapping]:
    """
    Read the table data from the underlying storage.

    Documents and doc_ids are NOT yet transformed, as
    we may not want to convert *all* documents when returning
    only one document for example.
    """

    # Retrieve the tables from the storage
    tables = self._storage.read()

    if tables is None:
        # The database is empty
        return {}

    # Retrieve the current table's data
    try:
        table = tables[self.name]
    except KeyError:
        # The table does not exist yet, so it is empty
        return {}

    return table

def resolve_variables(
    values: Iterable[Tuple[str, Optional[str]]],
    override: bool,
) -> Mapping[str, Optional[str]]:
    new_values: Dict[str, Optional[str]] = {}

    for name, value in values:
        if value is None:
            result = None
        else:
            atoms = parse_variables(value)
            env: Dict[str, Optional[str]] = {}
            if override:
                env.update(os.environ)  # type: ignore
                env.update(new_values)
            else:
                env.update(new_values)
                env.update(os.environ)  # type: ignore
            result = "".join(atom.resolve(env) for atom in atoms)

        new_values[name] = result

    return new_values

def parse_variables(value: str) -> Iterator[Atom]:
    cursor = 0

    for match in _posix_variable.finditer(value):
        (start, end) = match.span()
        name = match["name"]
        default = match["default"]

        if start > cursor:
            yield Literal(value=value[cursor:start])

        yield Variable(name=name, default=default)
        cursor = end

    length = len(value)
    if cursor < length:
        yield Literal(value=value[cursor:length])

def dict(self) -> Dict[str, Optional[str]]:
    """Return dotenv as dict"""
    if self._dict is not None:
        return self._dict

    raw_values = self.parse()

    if self.interpolate:
        self._dict = OrderedDict(
            resolve_variables(raw_values, override=self.override)
        )
    else:
        self._dict = OrderedDict(raw_values)

    return self._dict

def set_as_environment_variables(self) -> bool:
    """
    Load the current dotenv as system environment variable.
    """
    if not self.dict():
        return False

    for k, v in self.dict().items():
        if k in os.environ and not self.override:
            continue
        if v is not None:
            os.environ[k] = v

    return True

