        self._add_action_func(self.before_sleep)

    self._add_action_func(lambda rs: DoSleep(rs.upcoming_sleep))

class stop_after_attempt(stop_base):
    """Stop when the previous attempt >= max_attempt."""

    def __init__(self, max_attempt_number: int) -> None:
        self.max_attempt_number = max_attempt_number

    @override
    def __call__(self, retry_state: "RetryCallState") -> bool:
        return retry_state.attempt_number >= self.max_attempt_number

def reraise(self) -> t.NoReturn:
    if self.last_attempt.failed:
        exc = self.last_attempt.exception()
        # When the user explicitly raises TryAgain (typically from within
        # an "except" block), surface the underlying exception that caused
        # the retry rather than the opaque TryAgain sentinel.
        if isinstance(exc, TryAgain):
            cause = exc.__cause__ or exc.__context__
            if cause is not None:
                raise cause.with_traceback(cause.__traceback__) from None
        raise self.last_attempt.result()
    raise self

def set_as_environment_variables(self) -> bool:
    """
    Load the current dotenv as system environment variable.
    """
    if not self.dict():
        return False

    for k, v in self.dict().items():
        if k in os.environ and not self.override:
            continue
        if v is not None:
            os.environ[k] = v

    return True

def dict(self) -> Dict[str, Optional[str]]:
    """Return dotenv as dict"""
    if self._dict is not None:
        return self._dict

    raw_values = self.parse()

    if self.interpolate:
        self._dict = OrderedDict(
            resolve_variables(raw_values, override=self.override)
        )
    else:
        self._dict = OrderedDict(raw_values)

    return self._dict

@cli.command(
    context_settings={
        "allow_extra_args": True,
        "allow_interspersed_args": False,
        "ignore_unknown_options": True,
    }
)
@click.pass_context
@click.option(
    "--override/--no-override",
    default=True,
    help="Override variables from the environment file with those from the .env file.",
)
@click.argument("commandline", nargs=-1, type=click.UNPROCESSED)
def run(ctx: click.Context, override: bool, commandline: tuple[str, ...]) -> None:
    """Run command with environment variables present."""
    file = ctx.obj["FILE"]
    if not os.path.isfile(file):
        raise click.BadParameter(
            f"Invalid value for '-f' \"{file}\" does not exist.", ctx=ctx
        )
    dotenv_as_dict = {
        k: v
        for (k, v) in DotEnv(file, override=override, encoding="utf-8").dict().items()
        if v is not None and (override or k not in os.environ)
    }

    if not commandline:
        click.echo("No command given.")
        sys.exit(1)

    run_command([*commandline, *ctx.args], dotenv_as_dict)
